import os
import json
from datetime import datetime
from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
import openai
from supermemory import Supermemory
from typing import List, Dict

app = Flask(__name__)
CORS(app)

MODAL_BASE_URL = os.environ.get("MODAL_BASE_URL")
if not MODAL_BASE_URL:
    raise ValueError("MODAL_BASE_URL not set in secrets")

SUPERMEMORY_API_KEY = os.environ.get("SUPERMEMORY_API_KEY")
if not SUPERMEMORY_API_KEY:
    raise ValueError("SUPERMEMORY_API_KEY not set in secrets")

sm_client = Supermemory(api_key=SUPERMEMORY_API_KEY)
openai_client = openai.OpenAI(
    base_url=f"{MODAL_BASE_URL.rstrip('/')}/v1",
    api_key="not-needed"
)

CONTAINER_TAG = "personal_chat"

@app.route('/')
def serve_frontend():
    return send_from_directory('.', 'index.html')

@app.route('/manifest.json')
def manifest():
    return jsonify({
        "name": "GLM Chat",
        "short_name": "GLMChat",
        "description": "Modern AI Chat PWA",
        "start_url": "/",
        "display": "standalone",
        "background_color": "#ffffff",
        "theme_color": "#4ecdc4",
        "icons": [
            {
                "src": "data:image/svg+xml;base64,",
                "sizes": "192x192",
                "type": "image/svg+xml"
            }
        ]
    })

@app.route('/sw.js')
def service_worker():
    return """
self.addEventListener('fetch', e => {
  e.respondWith(fetch(e.request));
});
"""

@app.route('/chat', methods=['POST'])
def chat():
    data = request.json
    messages: List[Dict] = data.get('messages', [])
    if not messages:
        return jsonify({'error': 'No messages provided'}), 400

    try:
        # Search for relevant memories
        query = messages[-1]['content']
        search_results = sm_client.search.execute(
            q=query,
            limit=50,
            container_tag=CONTAINER_TAG
        )
        memory_context = ""
        if hasattr(search_results, 'results') and search_results.results:
            relevant_chunks = []
            for result in search_results.results[:20]:
                if hasattr(result, 'chunks') and result.chunks:
                    relevant_chunks.extend([chunk.content for chunk in result.chunks if hasattr(chunk, 'is_relevant') and chunk.is_relevant])
            memory_context = "\\n".join(relevant_chunks[:10])

        # Build enhanced messages with memory context
        system_prompt = "You are a helpful AI assistant. Use the following context to inform your response if relevant:\\n" + memory_context if memory_context else "You are a helpful AI assistant."
        enhanced_messages = [{"role": "system", "content": system_prompt}] + messages

        # Call the model
        response = openai_client.chat.completions.create(
            model="glm-5-fp8",
            messages=enhanced_messages,
            temperature=1.0,
            top_p=1.0,
            stream=False,
            max_tokens=4096
        )
        ai_response = response.choices[0].message.content

        # Save the conversation to supermemory
        conv_content = json.dumps([
            {"role": msg["role"], "content": msg["content"]} for msg in messages
        ] + [{"role": "assistant", "content": ai_response}], ensure_ascii=False)
        sm_client.documents.add(
            content=conv_content,
            container_tag=CONTAINER_TAG,
            custom_id=f"chat_{datetime.now().isoformat()}"
        )

        return jsonify({'response': ai_response})

    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)), debug=False)
