## Backend FastAPI + supermemory v3

A backend egy FastAPI app `main.py`-ban, ami SSE‑streamet ad vissza a Modal vLLM szerver OpenAI‑kompatibilis `/v1/chat/completions` végpontjáról, és minden lezárt választ felküld a supermemory `/v3/documents` API‑ra, a hivatalos `Authorization: Bearer` fejlécformátummal.  A supermemory keresés a `/v3/search` végpontot hívja `q` mezővel, az API quickstart szerinti módon, a válasz struktúráját rugalmasan kezelve, így schema‑változás esetén sem dől össze.[4][2]

```python
import os
import json
import uuid

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, StreamingResponse
from fastapi.middleware.cors import CORSMiddleware
import requests

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/", response_class=HTMLResponse)
async def root():
    with open("index.html", "r", encoding="utf-8") as f:
        return f.read()


@app.post("/chat")
async def chat(request: Request) -> StreamingResponse:
    data = await request.json()
    messages = data.get("messages", [])
    session_id = data.get("session_id", str(uuid.uuid4()))

    if not isinstance(messages, list):
        messages = []

    query = ""
    if messages:
        last_message = messages[-1]
        if isinstance(last_message, dict):
            query = last_message.get("content", "")

    supermemory_api_key = os.getenv("SUPERMEMORY_API_KEY")
    memory_context = ""

    if supermemory_api_key and query:
        headers = {
            "Authorization": f"Bearer {supermemory_api_key}",
            "Content-Type": "application/json",
        }
        try:
            search_resp = requests.post(
                "",
                json={"q": query},
                headers=headers,
                timeout=30,
            )
            search_texts = []
            if search_resp.ok:
                try:
                    search_data = search_resp.json()
                except Exception:
                    search_data = {}
                if isinstance(search_data, dict):
                    for key in ("memories", "results", "documents", "data"):
                        items = search_data.get(key)
                        if isinstance(items, list):
                            for item in items:
                                if isinstance(item, dict):
                                    parts = []
                                    for field in ("summary", "content", "raw", "text", "title"):
                                        value = item.get(field)
                                        if isinstance(value, str):
                                            parts.append(value)
                                    if parts:
                                        search_texts.append(" ".join(parts))
                if search_texts:
                    memory_context = "\n\n".join(search_texts[:10])
        except Exception:
            memory_context = ""

    if memory_context:
        system_preamble = {
            "role": "system",
            "content": "Használd a következő hosszú távú memóriából származó kontextust, de válaszolj természetesen:\n\n" + memory_context,
        }
        messages = [system_preamble] + messages

    modal_base_url = os.getenv("MODAL_BASE_URL", "").rstrip("/")
    if not modal_base_url:
        modal_base_url = ""

    proxy_payload = {
        "model": "glm-4.7-fp8",
        "messages": messages,
        "temperature": 1.0,
        "top_p": 1.0,
        "top_k": 1,
        "stream": True,
        "max_tokens": 16384,
    }

    proxy_req = requests.post(
        modal_base_url + "/v1/chat/completions",
        json=proxy_payload,
        headers={"Content-Type": "application/json", "Accept": "text/event-stream"},
        stream=True,
    )

    async def stream_gen():
        full_response = ""
        for line in proxy_req.iter_lines():
            if not line:
                continue
            decoded_line = line.decode("utf-8").strip()
            if not decoded_line:
                continue
            if decoded_line.startswith("data: "):
                chunk = decoded_line[6:]
            else:
                continue
            if chunk == "[DONE]":
                yield "data: [DONE]\n\n"
                if supermemory_api_key:
                    headers = {
                        "Authorization": f"Bearer {supermemory_api_key}",
                        "Content-Type": "application/json",
                    }
                    document_content = json.dumps(
                        {
                            "session_id": session_id,
                            "messages": messages + [{"role": "assistant", "content": full_response}],
                        },
                        ensure_ascii=False,
                    )
                    try:
                        requests.post(
                            "",
                            json={"content": document_content},
                            headers=headers,
                            timeout=30,
                        )
                    except Exception:
                        pass
                break
            try:
                chunk_data = json.loads(chunk)
            except Exception:
                continue
            choices = chunk_data.get("choices")
            if not isinstance(choices, list) or not choices:
                continue
            delta = choices[0].get("delta") or {}
            piece = delta.get("content") or ""
            if not isinstance(piece, str):
                piece = ""
            if piece:
                full_response += piece
            yield "data: " + json.dumps(chunk_data, ensure_ascii=False) + "\n\n"

    return StreamingResponse(stream_gen(), media_type="text/event-stream")
```

