    <script>
        const chatContainer = document.getElementById("chat-container");
        const messageInput = document.getElementById("message-input");
        const sendBtn = document.getElementById("send-btn");
        const welcome = document.getElementById("welcome");

        let sessionId = localStorage.getItem("glm47_session_id");
        if (!sessionId && window.crypto && window.crypto.randomUUID) {
            sessionId = crypto.randomUUID();
            localStorage.setItem("glm47_session_id", sessionId);
        } else if (!sessionId) {
            sessionId = String(Date.now()) + "-" + Math.random().toString(16).slice(2);
            localStorage.setItem("glm47_session_id", sessionId);
        }

        let sending = false;

        function appendMessage(role, text) {
            const row = document.createElement("div");
            row.className = "message-row " + role;
            const bubble = document.createElement("div");
            bubble.className = "message-bubble";
            bubble.textContent = text;
            row.appendChild(bubble);
            chatContainer.appendChild(row);
            chatContainer.scrollTop = chatContainer.scrollHeight;
        }

        function createAssistantMessage() {
            const row = document.createElement("div");
            row.className = "message-row assistant";
            const bubble = document.createElement("div");
            bubble.className = "message-bubble";
            const spinner = document.createElement("div");
            spinner.className = "loading-spinner";
            bubble.appendChild(spinner);
            row.appendChild(bubble);
            chatContainer.appendChild(row);
            chatContainer.scrollTop = chatContainer.scrollHeight;
            return bubble;
        }

        function setSendingState(active) {
            sending = active;
            messageInput.disabled = active;
            if (active) {
                sendBtn.innerHTML = "";
                const spinner = document.createElement("div");
                spinner.className = "loading-spinner";
                sendBtn.appendChild(spinner);
            } else {
                sendBtn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"></path></svg>';
            }
        }

        async function sendMessage() {
            const value = messageInput.value.trim();
            if (!value || sending) {
                return;
            }

            if (welcome) {
                welcome.style.display = "none";
            }

            appendMessage("user", value);
            messageInput.value = "";
            messageInput.style.height = "auto";
            const assistantBubble = createAssistantMessage();
            let fullContent = "";
            setSendingState(true);

            try {
                const response = await fetch("/chat", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify({
                        messages: [
                            { role: "user", content: value }
                        ],
                        session_id: sessionId
                    })
                });

                if (!response.ok || !response.body) {
                    assistantBubble.textContent = "Hiba történt a válasz közben.";
                    setSendingState(false);
                    return;
                }

                const reader = response.body.getReader();
                const decoder = new TextDecoder("utf-8");
                let buffer = "";

                while (true) {
                    const { value: chunk, done } = await reader.read();
                    if (done) {
                        break;
                    }
                    buffer += decoder.decode(chunk, { stream: true });
                    const parts = buffer.split("\n\n");
                    buffer = parts.pop() || "";
                    for (const part of parts) {
                        const line = part.trim();
                        if (!line || !line.startsWith("data:")) {
                            continue;
                        }
                        const data = line.slice(5).trim();
                        if (!data) {
                            continue;
                        }
                        if (data === "[DONE]") {
                            setSendingState(false);
                            return;
                        }
                        try {
                            const parsed = JSON.parse(data);
                            const choices = parsed.choices || [];
                            if (!choices.length) {
                                continue;
                            }
                            const delta = choices[0].delta || {};
                            const piece = typeof delta.content === "string" ? delta.content : "";
                            if (piece) {
                                fullContent += piece;
                                assistantBubble.textContent = fullContent;
                                chatContainer.scrollTop = chatContainer.scrollHeight;
                            }
                        } catch (e) {
                        }
                    }
                }

                setSendingState(false);
            } catch (e) {
                assistantBubble.textContent = "Nem sikerült kapcsolódni a szerverhez.";
                setSendingState(false);
            }
        }

        messageInput.addEventListener("input", () => {
            messageInput.style.height = "auto";
            messageInput.style.height = Math.min(messageInput.scrollHeight, 120) + "px";
        });

        messageInput.addEventListener("keydown", (event) => {
            if (event.key === "Enter" && !event.shiftKey) {
                event.preventDefault();
                sendMessage();
            }
        });

        sendBtn.addEventListener("click", () => {
            sendMessage();
        });

        if ("serviceWorker" in navigator) {
            const swCode = `
                self.addEventListener("install", event => {
                    self.skipWaiting();
                });
                self.addEventListener("activate", event => {
                    self.clients.claim();
                });
                self.addEventListener("fetch", event => {
                    event.respondWith(
                        caches.open("glm-chat-cache").then(cache => {
                            return cache.match(event.request).then(response => {
                                return response || fetch(event.request).then(networkResponse => {
                                    cache.put(event.request, networkResponse.clone());
                                    return networkResponse;
                                });
                            });
                        })
                    );
                });
            `;
            const swBlob = new Blob([swCode], { type: "text/javascript" });
            const swUrl = URL.createObjectURL(swBlob);
            navigator.serviceWorker.register(swUrl).catch(() => {});
        }
    </script>
